function serializeSections(sections) {
  if (!isPlainObject(sections)) {
    throw new TypeError("sections must be a plain object");
  }

  var pairs = [];

  for (var i = 0, sectionKeys = Object.keys(sections); i < sectionKeys.length; i++) {
    var section = sectionKeys[i];
    var fields = sections[section];

    if (fields === undefined) continue;
    if (!isPlainObject(fields)) {
      throw new TypeError("section values must be plain objects");
    }

    for (var j = 0, fieldKeys = Object.keys(fields); j < fieldKeys.length; j++) {
      var field = fieldKeys[j];
      var values = fields[field];

      if (values === undefined) continue;
      if (!Array.isArray(values) || !isDenseArray(values)) {
        throw new TypeError("field values must be dense arrays");
      }

      var encodedName = encodeRFC3986(section + "[" + field + "]");

      for (var k = 0; k < values.length; k++) {
        if (typeof values[k] !== "string") {
          throw new TypeError("array values must be strings");
        }

        pairs.push([encodedName, encodeRFC3986(values[k])]);
      }
    }
  }

  pairs.sort(function (a, b) {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    if (a[1] < b[1]) return -1;
    if (a[1] > b[1]) return 1;
    return 0;
  });

  return pairs.map(function (pair) {
    return pair[0] + "=" + pair[1];
  }).join("&");
}

function isPlainObject(value) {
  if (value === null || typeof value !== "object") return false;
  var prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function isDenseArray(array) {
  for (var i = 0; i < array.length; i++) {
    if (!Object.prototype.hasOwnProperty.call(array, i)) return false;
  }
  return true;
}

function encodeRFC3986(value) {
  return encodeURIComponent(value).replace(/[!'()*]/g, function (character) {
    return "%" + character.charCodeAt(0).toString(16).toUpperCase();
  });
}
